// The optimized version below preserves this semantics, but:
//   * keeps path[i][k] in a register (aik) for each (k, i), so we do not
//     recompute / reload it for every j,
//   * uses a view (row_k) for row k to access path[k][j] with minimal
//     indexing overhead,
//   * expresses the loop nest using noarr traversers and for_dims<>
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		std::size_t k = get_index<'k'>(sk);

		// Create a 1D view of the k-th row: row_k[j] == path[k][j]
		// This is a zero-cost view (no data copy, layout preserved).
		auto row_k = path ^ noarr::fix<'i'>(k);

		// Next loop: iterate i (rows). We use for_dims<'i'> so that:
		//   - trav_i has 'i' fixed and iterates over 'j',
		//   - we can compute path[i][k] once per i and reuse it.
		traverser(path).template for_dims<'i'>([&](auto trav_i) {
			// Extract current row index i from the traverser
			std::size_t i = get_index<'i'>(trav_i);

			// Load path[i][k] once for this (k, i) pair and keep it in a register.
			// This is algebraically equivalent to the original code, because
			// path[i][k] is only ever (potentially) changed in the j == k
			// iteration, and in standard Floyd–Warshall setups
			// (no negative self-cycles) that update is a no-op:
			//   path[i][k] = min(path[i][k], path[i][k] + path[k][k])
			// so path[i][k] does not decrease within a fixed k-step.
			const num_t aik = path[noarr::idx<'i', 'j'>(i, k)];

			// Inner-most loop over j (columns) for this fixed (k, i).
			// trav_i.for_each iterates all j for the current i in row-major order.
			trav_i.for_each([&](auto sij) {
				// sij contains both 'i' and 'j'. The 'i' component matches the
			 // current row; the 'j' component selects the column. We can use
				// 'sij' directly as a state to index both 'path' and 'row_k';
				// for row_k, the extra 'i' index is simply ignored.

				// path[k][j] via the k-th row view; this uses the current j from sij.
				const num_t skj = row_k[sij];

				// Candidate path via intermediate vertex k
				const num_t via_k = aik + skj;

				// Reference to path[i][j] so we update in-place
				num_t &pij = path[sij];

				// Standard Floyd–Warshall relaxation
				if (via_k < pij)
					pij = via_k;
			});
		});
	});
#pragma endscop
}

} // namespace

