// Small helper: parallelize the topmost dimension of a traverser with OpenMP.
//
// The traverser iterator (from traverser_iter.hpp) iterates its topmost
// dimension and yields an inner traverser with that dimension fixed.
// This keeps all iteration expressed in Noarr abstractions.
template<class Traverser, class Func>
inline void omp_trav_for_each_dim(const Traverser &trav, const Func &f) {
	// When compiled without OpenMP support, this pragma is ignored by the compiler.
	#pragma omp parallel for
	for (auto inner_trav : trav) {
		// Each thread receives a disjoint subset of inner_trav's, so
		// as long as the body only writes through inner_trav, there
	 // are no data races.
		f(inner_trav);
	}
}

