	using namespace noarr;

	traverser(path).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		num_t value = static_cast<num_t>(i * j % 7 + 1);
		if (((i + j) % 13 == 0) || ((i + j) % 7 == 0) || ((i + j) % 11 == 0))
			value = static_cast<num_t>(999);

		path[state] = value;
	});
}

// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimized version:
//
// For each k, we first take a *snapshot* of the k-th column and k-th row
// into 1D temporary buffers:
//   col_k[i] = path[i][k]  (D^{k-1}[i][k])
//   row_k[j] = path[k][j]  (D^{k-1}[k][j])
//
// Then we update all pairs (i,j) as:
//   path[i][j] = min(path[i][j], col_k[i] + row_k[j])
//
// Because col_k and row_k hold values from the beginning of the k-iteration
// (i.e. D^{k-1}), this is algebraically identical to the standard
// Floyd–Warshall recurrence and thus preserves semantics.
//
// Advantages:
//  - We avoid repeatedly accessing path[i][k] and path[k][j] through a
//    strided 2D layout; instead we use contiguous 1D arrays.
//  - The outer i dimension is parallelized with OpenMP using traverser
//    iterators, while avoiding data races (col_k and row_k are read-only,
//    and each (i,j) cell is updated by exactly one thread).
//
// The asymptotic complexity stays O(n^3); the additional memory is O(n)
// (two temporaries of length n), which is negligible compared to the n^2
// elements of the path matrix and well within the requested bounds.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Temporary buffers holding the k-th column and k-th row
	// of the path matrix for the current iteration of k.
	std::vector<num_t> col_k(n);
	std::vector<num_t> row_k(n);

	// Traverser over the whole matrix, reused for every k.
	// Dimensions: 'i' (outer), 'j' (inner, contiguous in memory).
	auto full_trav = traverser(path);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// ------------------------------------------------------------------
		// Stage 1: snapshot row k and column k of D^{k-1}
		// ------------------------------------------------------------------

		// View of row k: fix 'i' = k, iterate over 'j'
		{
			auto row_view = path ^ noarr::fix<'i'>(k);
			traverser(row_view).for_each([&](auto sj) {
				const std::size_t j = get_index<'j'>(sj);
				// row_k[j] = D^{k-1}[k][j]
				row_k[j] = row_view[sj];
			});
		}

		// View of column k: fix 'j' = k, iterate over 'i'
		{
			auto col_view = path ^ noarr::fix<'j'>(k);
			traverser(col_view).for_each([&](auto si) {
				const std::size_t i = get_index<'i'>(si);
				// col_k[i] = D^{k-1}[i][k]
				col_k[i] = col_view[si];
			});
		}

		// ------------------------------------------------------------------
		// Stage 2: update all pairs (i,j) using the snapped row/column.
		//
		// We parallelize over the outer 'i' dimension; each thread gets
		// a disjoint subset of rows. For a fixed i, col_k[i] is reused
		// across all j in that row to reduce redundant loads.
		// ------------------------------------------------------------------
		omp_trav_for_each_dim(full_trav, [&](auto trav_i) {
			// trav_i has 'i' fixed and iterates over all remaining 'j'.
			const auto si = trav_i.state();
			const std::size_t i = get_index<'i'>(si);

			// D^{k-1}[i][k], reused for all j in this row
			const num_t dik = col_k[i];

			trav_i.for_each([&](auto sij) {
				const std::size_t j = get_index<'j'>(sij);

				// D^{k-1}[k][j] from the snapped row
				const num_t dkj = row_k[j];

				const num_t via_k = dik + dkj;
				num_t &pij = path[sij];

				// path[i][j] = min(path[i][j], via_k);
				if (via_k < pij)
					pij = via_k;
			});
		});
	});
#pragma endscop
