// Array initialization: mirrors the original C init_array
// Optimized to:
//  - hoist the row index 'i' out of the inner loop
//  - reuse (i + j) for all modulus computations
void init_array(auto path) {
	using namespace noarr;

	// Iterate row by row: outer dimension 'i', inner 'j'
	traverser(path).template for_dims<'i'>([&](auto trav_i) {
		const auto state_i = trav_i.state();
		const std::size_t i = get_index<'i'>(state_i);

		trav_i.for_each([&](auto state_ij) {
			const std::size_t j = get_index<'j'>(state_ij);

			const std::size_t prod = i * j;
			num_t value = static_cast<num_t>(prod % 7u + 1u);

			const std::size_t sum = i + j;
			if ((sum % 13u == 0u) || (sum % 7u == 0u) || (sum % 11u == 0u))
				value = static_cast<num_t>(999);

			path[state_ij] = value;
		});
	});
}

// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimizations:
//  - Keep the outer loop over k unchanged to preserve DP order.
//  - For each k, copy row k (path[k][j]) into a temporary 1D buffer once,
//    so every path[k][j] is loaded only once per k, instead of once per (i,j).
//    This is semantically safe because path[k][j] does not change during
//    iteration k for non-negative weights.
//  - For each i, load path[i][k] once and reuse it for all j in that row.
//  - Traverse path row-by-row ('i' outer, 'j' inner) to keep accesses
//    to path[i][j] and the k-th row buffer contiguous.
//  - Optionally parallelize the per-row work with OpenMP over 'i'.
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Temporary buffer for the k-th row: row_k[j] = path[k][j]
	// This is 1D over 'j' and adds only O(N) extra memory.
	auto row_struct = noarr::scalar<num_t>() ^ j_vec ^ noarr::set_length<'j'>(n);
	auto row_buf = noarr::make_bag(row_struct);
	auto row = row_buf.get_ref(); // copyable reference bag

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// ---------------------------------------------------------------------
		// 1) Materialize the k-th row into a contiguous 1D buffer.
		//    This reduces loads of path[k][j] from O(N^2) per k to O(N) per k.
		// ---------------------------------------------------------------------
		traverser(row).for_each([&](auto sj) {
			const std::size_t j = get_index<'j'>(sj);
			row[sj] = path[noarr::idx<'i', 'j'>(k, j)]; // row_k[j] = path[k][j]
		});

		// ---------------------------------------------------------------------
		// 2) For each i, update row i using:
		//        via_k = path[i][k] + row_k[j]
		//    We:
		//      - parallelize across 'i' (rows) when OpenMP is enabled
		//      - load path[i][k] once per row and reuse it for all j
		// ---------------------------------------------------------------------

		// Use the traverser iterator so that each iteration of the range-based
		// for loop corresponds to a fixed 'i' (one row of the matrix).
#ifdef _OPENMP
		#pragma omp parallel for schedule(static)
#endif
		for (auto trav_i : traverser(path)) {
			// trav_i has 'i' fixed, 'j' varying
			const auto state_i = trav_i.state();
			const std::size_t i = get_index<'i'>(state_i);

			// path[i][k] is constant for this (k, i) pair within the inner j-loop.
			const num_t dist_ik = path[noarr::idx<'i', 'j'>(i, k)];

			// Traverse all columns j for the current row i
