				const std::size_t j = get_index<'j'>(state_ij);

				const num_t via_k = dist_ik + row[noarr::idx<'j'>(j)];
				num_t &p_ij = path[state_ij];

				// Branch form instead of ?: for easier vectorization
				if (via_k < p_ij)
					p_ij = via_k;
			});
		}
	});
#pragma endscop
