#include <vector> // temporary buffer for one k-row

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "floyd-warshall.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// path[i][j] in C: i = row, j = column, row-major
	// => 'j' inner, 'i' outer
	DEFINE_PROTO_STRUCT(path_layout, j_vec ^ i_vec);
} tuning;

// Array initialization: mirrors the original C init_array
void init_array(auto path) {
	using namespace noarr;

	traverser(path).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		num_t value = static_cast<num_t>(i * j % 7 + 1);
		if (((i + j) % 13 == 0) || ((i + j) % 7 == 0) || ((i + j) % 11 == 0))
			value = static_cast<num_t>(999);

		path[state] = value;
	});
}

// Main computational kernel: Floyd–Warshall
// Original C loops:
//
// for (k = 0; k < _PB_N; k++)
//   for (i = 0; i < _PB_N; i++)
//     for (j = 0; j < _PB_N; j++)
//       path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
//                      path[i][j] : path[i][k] + path[k][j];
//
// Optimized version notes:
//
// 1. We still iterate k on the outside, then i, then j, preserving the
//    original update order and semantics.
// 2. For each fixed k, we:
//      - Read the whole row path[k][j] into a temporary buffer row_k[j].
//        Each value path[k][j] is therefore loaded only once per k,
//        instead of once per (i,j) pair.
//      - For each i, we load path[i][k] once into a scalar dist_ik.
//        This value is constant over all j for fixed (k,i) under the
//        assumptions of this benchmark (non‑negative edge weights).
//      - The inner j-loop then uses only:
//          * the buffered row_k[j],
//          * the scalar dist_ik,
//          * the current path[i][j].
//    This reduces the number of matrix loads per (k,i,j) iteration from
//    3 (path[i][j], path[i][k], path[k][j]) to effectively ~1
//    (path[i][j]) plus amortized O(1/n) for the preloads, improving
//    cache behavior and memory bandwidth usage while preserving results.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Temporary buffer for one row path[k][j] per k.
	// Allocated once; reused for every k.
	std::vector<num_t> row_k(n);

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// ------------------------------------------------------------------
		// 1) Preload the whole k-th row: row_k[j] = path[k][j]
		// ------------------------------------------------------------------
		//
		// We create a 1D view of the matrix where 'i' is fixed to k, so the
		// only varying index is 'j'.
		//
		// This view is layout-preserving; only the logical interface changes.
		//
		auto row_k_view = path ^ noarr::fix<'i'>(k);

		traverser(row_k_view).for_each([&](auto sj) {
			const std::size_t j = get_index<'j'>(sj);
			row_k[j] = row_k_view[sj];
		});

		// ------------------------------------------------------------------
		// 2) Main loops over i and j in row-major order
		// ------------------------------------------------------------------
		//
		// For each i, we:
		//   - load dist_ik = path[i][k] once outside the inner j-loop,
		//   - iterate j via traverser, accessing:
		//       * row_k[j] (already in a contiguous buffer),
		//       * path[i][j] (matrix element to be potentially updated).
		//
		// The original C code reads path[i][k] and path[k][j] in every
	 // (i,j) iteration. Here we hoist both:
		//   - path[k][j] into row_k[j] (per k),
		//   - path[i][k] into dist_ik (per (k,i)).
		//
		// This transformation preserves semantics for this benchmark,
		// because:
		//   - path[k][j] is independent of i during a fixed k-iteration,
		//   - path[i][k] is not modified during the k-iteration in a way
		//     that would influence later j (the standard Floyd–Warshall
		//     recurrence with non-negative weights does not decrease
		//     path[i][k] at step k).
		//
		traverser(path).template for_dims<'i'>([&](auto trav_row) {
			// trav_row has 'i' fixed; only 'j' varies in trav_row.for_each
			auto si = trav_row.state();
			const std::size_t i = get_index<'i'>(si);

			// Distance from i to k is constant for all j (for this k,i)
			const num_t dist_ik = path[noarr::idx<'i', 'j'>(i, k)];

			// Inner loop over j for fixed (k, i)
			trav_row.for_each([&](auto sij) {
				const std::size_t j = get_index<'j'>(sij);

				// path[k][j] comes from the preloaded row
				const num_t dist_kj = row_k[j];

				num_t &pij = path[sij];
				const num_t via_k = dist_ik + dist_kj;

				if (via_k < pij)
					pij = via_k;
			});
		});
	});
#pragma endscop
}

